mapper.select:
SELECT  FROM promotion_pairing_session
WHERE session_token_hash = #{tokenHash}
LIMIT 1

SELECT  FROM promotion_pairing_session
WHERE active_protocol_account_id = #{protocolAccountId}
LIMIT 1

SELECT  FROM promotion_pairing_session
WHERE id = #{id} AND tenant_id = #{tenantId}
FOR UPDATE

SELECT  FROM promotion_pairing_session
WHERE status IN (1, 2, 3)
  AND expires_at <= #{now}
ORDER BY expires_at, id
LIMIT #{limit}

mapper.update:
UPDATE promotion_pairing_session
SET pairing_id = #{pairingId}, expires_at = #{expiresAt}, updated_at = #{updatedAt}
WHERE id = #{id} AND tenant_id = #{tenantId} AND status IN (1, 2)

UPDATE promotion_pairing_session
SET pairing_code = #{pairingCode}, status = 2, expires_at = #{expiresAt}, updated_at = #{updatedAt}
WHERE id = #{id} AND tenant_id = #{tenantId}
  AND protocol_account_id = #{protocolAccountId} AND status IN (1, 2)

UPDATE promotion_pairing_session
SET status = 3, pairing_code = NULL, updated_at = #{updatedAt}
WHERE id = #{id} AND tenant_id = #{tenantId} AND status IN (1, 2)

UPDATE promotion_pairing_session
SET status = 4, pairing_code = NULL, account_id = #{accountId}, completed_at = #{completedAt}, updated_at = #{completedAt}
WHERE id = #{id} AND tenant_id = #{tenantId} AND status = 3
